 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    # Bottom-row 5 markers select columns; colors propagate upward,
    # with each original non-background cell starting a new segment.
    for c in range(w):
        if grid[h - 1][c] != 5:
            continue
        color = None
        for r in range(h - 1, -1, -1):
            if grid[r][c] != 0:
                color = grid[r][c]
            elif color is not None:
                out[r][c] = color
    return out
